async function submitSupportRequest(data) {
  if (!data.message || data.message.length < 10) throw new Error("Enter at least 10 characters for support.");
  let ticketRef = "";
  try {
    const result = await api("/v1/support/tickets", {
      method: "POST",
      body: { category: data.category, message: data.message }
    });
    ticketRef = result.ticketRef || "";
  } catch (error) {
    // Support API may be deployed after the customer PWA; keep the user-facing request captured locally.
    const tickets = readJson("titopay_support_requests") || [];
    tickets.push({ category: data.category, message: data.message, createdAt: new Date().toISOString() });
    localStorage.setItem("titopay_support_requests", JSON.stringify(tickets));
  }
  const history = document.querySelector("[data-support-history]");
  if (history) {
    // Contact TitoPay screen: keep it open so the new request appears in the
    // list below, where Customer Care replies will also land.
    const form = document.querySelector('form[data-form="support"]');
    if (form) form.reset();
    await refreshMySupportRequests();
  } else {
    closeModal();
  }
  showToast(ticketRef ? `Support request submitted. Reference ${ticketRef}. A receipt email is on its way.` : "Support request submitted.");
}
async function submitSupportRating(rating) {
  const button = document.querySelector(`[data-support-rating="${String(rating)}"]`);
  const ticketId = button?.dataset.supportTicket || "";
  const feedback = (await askForValue({
    title: "Close this request",
    body: "Anything you would like Customer Care to know before it closes?",
    label: "Feedback", placeholder: "Optional", maxLength: 300, confirmLabel: "Close request"
  })) || "";
  try {
    await api("/v1/chatbot/ratings", {
      method: "POST",
      body: {
        ticketId,
        rating: Number(rating),
        feedback,
        accountType: state.accountType
      }
    });
  } catch (error) {
    const ratings = readJson("titopay_support_ratings") || [];
    ratings.push({ ticketId, rating: Number(rating), feedback, createdAt: new Date().toISOString() });
    localStorage.setItem("titopay_support_ratings", JSON.stringify(ratings));
  }
  addInAppNotification({
    id: `support-rating-${ticketId}-${rating}`,
    title: "Service rating sent",
    body: "Thank you. Your service rating has been sent to TitoPay Customer Care.",
    category: "support_rating",
    metadata: {
      ticketId,
      rating: Number(rating),
      notificationType: "support_rating"
    }
  });
  // The stars used to stay up after being pressed, so the same conversation
  // could be rated over and over and the card sat there implying it had not
  // been answered. Worse, the card is re-rendered from the conversation status
  // on every four-second poll, so simply removing it would have put it straight
  // back. The ticket is recorded as rated — which renderSupportRating now
  // checks — and the card turns into its own acknowledgement rather than a
  // chat message, because a chat message would be wiped by the next rebuild.
  markSupportTicketRated(ticketId);
  const card = document.querySelector(".support-rating");
  if (card) {
    card.innerHTML = `<strong>Thanks for the feedback.</strong><p class="support-rating-done">Your rating has been sent to TitoPay Customer Care.</p>`;
    card.dataset.supportRated = "true";
  }
}
function isFocusRestorationTarget(element) {
  return element instanceof HTMLElement
    && element !== document.body
    && element !== document.documentElement;
}

