/* ---- Group chat and meetings: members talk, organisers pin decisions,
   and closing a meeting compiles the minutes and emails them to everyone. */
function openStockvelChatModal(groupId) {
  const group = state.stockvel?.detail?.id === groupId ? state.stockvel.detail : (state.stockvel?.detail || (state.stockvel?.groups || []).find((item) => item.id === groupId));
  const id = groupId || group?.id;
  if (!id) { showToast("Open the group first.", "error"); return; }
  state.stockvelChat = { groupId: id, groupName: group?.name || "Savings group", canManage: Boolean(group?.canManage), meetings: [] };
  openModal(`
    <div class="modal-head">
      <div><p class="eyebrow">${esc(state.stockvelChat.groupName)}</p><h2>Group chat</h2><p class="lead">Talk as a group. Organisers pin decisions; closing a meeting turns the conversation into minutes for everyone.</p></div>
      <button class="icon-btn" data-close aria-label="Close">${icon("x")}</button>
    </div>
    <div data-sv-meeting-bar></div>
    <section class="activity-list" data-sv-chat style="max-height:44vh;overflow-y:auto"><p class="field-hint">Loading the conversation…</p></section>
    <form class="form-grid" data-form="stockvel-chat" style="margin-top:8px">
      <input type="hidden" name="groupId" value="${esc(id)}">
      <div class="field"><textarea name="message" minlength="1" maxlength="1000" required placeholder="Message the group" rows="2"></textarea></div>
      <button class="btn primary" type="submit">${icon("send")} Send to the group</button>
    </form>
    <div data-sv-minutes style="margin-top:10px"></div>
  `);
  refreshStockvelGroupChat();
}
async function refreshStockvelGroupChat() {
  const chat = state.stockvelChat;
  if (!chat) return;
  const host = document.querySelector("[data-sv-chat]");
  const meetingBar = document.querySelector("[data-sv-meeting-bar]");
  const minutesHost = document.querySelector("[data-sv-minutes]");
  try {
    const [messagesResult, detailResult] = await Promise.all([
      api(`${STOCKVEL_PATH}/${encodeURIComponent(chat.groupId)}/messages`),
      api(`${STOCKVEL_PATH}/${encodeURIComponent(chat.groupId)}`).catch(() => null)
    ]);
    const meetings = detailResult?.group?.meetings || [];
    chat.meetings = meetings;
    chat.canManage = detailResult?.group ? Boolean(detailResult.group.can_manage) : chat.canManage;
    const openMeeting = meetings.find((meeting) => meeting.status === "open");
    if (meetingBar) {
      meetingBar.innerHTML = openMeeting
        ? `<section class="integration-note" style="display:flex;justify-content:space-between;align-items:center;gap:8px;background:#e8efff">
             <span><strong>Meeting in session</strong><br><small>${esc(openMeeting.title)} · everything said now goes into the minutes${chat.canManage ? " · tap a message to pin it as a decision" : ""}</small></span>
             ${chat.canManage ? `<button class="btn secondary" type="button" data-sv-meeting-close="${esc(openMeeting.id)}">End & compile minutes</button>` : ""}
           </section>`
        : chat.canManage
          ? `<div class="auth-actions" style="margin-bottom:8px"><button class="btn secondary" type="button" data-sv-meeting-open>${icon("check-circle")} Open a meeting</button></div>`
          : "";
    }
    if (host) {
      const items = messagesResult.items || [];
      const myId = state.user?.id;
      host.innerHTML = items.length ? items.map((message) => `
        <div style="margin:7px 0;display:flex;flex-direction:column;align-items:${message.userId === myId ? "flex-end" : "flex-start"}" ${chat.canManage ? `data-sv-decision="${esc(message.id)}" role="button" tabindex="0" title="Tap to pin as a decision"` : ""}>
          <div style="max-width:85%;background:${message.isDecision ? "#fdf3e2" : message.userId === myId ? "#2f5cff" : "#eef2fa"};color:${message.isDecision ? "#8a5b00" : message.userId === myId ? "#fff" : "#0b1f3f"};border-radius:14px;padding:8px 12px">
            ${message.isDecision ? `<small style="display:block;font-weight:700">DECISION</small>` : ""}
            <small style="display:block;opacity:0.75">${esc(message.name || message.username || "Member")}</small>
            ${esc(message.message)}
          </div>
          <small class="field-hint" style="margin-top:2px">${esc(new Date(message.createdAt).toLocaleString("en-ZA", { dateStyle: "short", timeStyle: "short" }))}</small>
        </div>`).join("")
        : `<p class="field-hint">No messages yet. Whatever the group says here stays visible to every member.</p>`;
      host.scrollTop = host.scrollHeight;
    }
    if (minutesHost) {
      const closed = meetings.filter((meeting) => meeting.status === "closed" && meeting.minutes);
      minutesHost.innerHTML = closed.length ? `
        <p class="field-hint" style="margin:0 0 4px"><strong>Minutes</strong>: compiled when each meeting closed, and emailed to every member.</p>
        ${closed.map((meeting) => `
          <details class="integration-note" style="margin:6px 0">
            <summary style="cursor:pointer"><strong>${esc(meeting.title)}</strong> · ${esc(new Date(meeting.closed_at).toLocaleDateString("en-ZA"))}</summary>
            <pre style="white-space:pre-wrap;font-family:inherit;font-size:12.5px;margin:8px 0 0">${esc(meeting.minutes)}</pre>
          </details>`).join("")}` : "";
    }
  } catch (error) {
    if (host) host.innerHTML = `<p class="field-hint">${esc(friendlyFormError(error, "stockvel"))}</p>`;
  }
}
// The wizard's final submit. Creating a group is free - no transaction, no
// fee - so it goes straight to the stokvel API. The member list is real:
// every registered person named there receives the invite code in their app
// and email, and anyone not on TitoPay is reported back by name.
async function submitStockvelCreate(form, data) {
  const name = String(data.recipient || "").trim();
  if (name.length < 2) throw new Error("Give the group a name first.");
  const members = normalizeRecipientList(data.members || "", data.memberMethod || "auto");
  const created = await api(STOCKVEL_PATH, {
    method: "POST",
    body: {
      name,
      description: data.description || "",
      cadence: data.cadence || "monthly",
      contributionAmount: data.amount || "0",
      goalAmount: data.stockvelSavingsGoal || null,
      memberLimit: data.memberLimit || null,
      status: "active"
    }
  });
  const group = created.group || created;
  let inviteSummary = "";
  if (members.length) {
    try {
      const invites = await api(`${STOCKVEL_PATH}/${encodeURIComponent(group.id)}/invitations`, {
        method: "POST",
        body: { identifiers: members }
      });
      const sent = (invites.invited || []).length;
      inviteSummary = sent ? `${sent} invitation${sent === 1 ? "" : "s"} sent.` : "";
      if ((invites.notRegistered || []).length) {
        inviteSummary += ` Not on TitoPay yet: ${invites.notRegistered.join(", ")} - share the code with them directly.`;
      }
    } catch {
      inviteSummary = "The group is created, but the invitations could not be sent. Share the invite code from the group screen.";
    }
  }
  closeModal();
  await loadStockvelGroups({ force: true }).catch(() => {});
  openStockvelModal();
  showToast(`"${name}" is live. Invite code ${group.inviteCode || group.invite_code}. ${inviteSummary}`.trim());
}
// A contribution is a confirmed money action: the member sees the amount,
// the fee and the treasurer holding the money before anything moves.
async function submitStockvelContribution(form, data) {
  const amount = Number(String(data.amount || "").replace(/[^\d.]/g, ""));
  if (!Number.isFinite(amount) || amount <= 0) throw new Error("Enter a valid contribution amount.");
  const groupId = data.stockvelGroupId;
  const preview = await api(`${STOCKVEL_PATH}/${encodeURIComponent(groupId)}/contributions/preview?amount=${encodeURIComponent(amount)}`);
  const feeLine = Number(preview.fee) > 0 ? `Fee: ${money(preview.fee)}. Total: ${money(preview.total)}.` : "No fee.";
  const confirmed = await askToConfirm({
    title: `Contribute ${money(preview.amount)}?`,
    body: `${money(preview.total)} leaves your wallet for "${preview.groupName}". ${feeLine} The money is held by ${preview.treasurer}, the group's organiser, and this contribution appears on the register every member sees.`,
    confirmLabel: "Contribute now"
  });
  if (!confirmed) return;
  const result = await api(`${STOCKVEL_PATH}/${encodeURIComponent(groupId)}/contributions`, {
    method: "POST",
    body: { amount, cycle: data.reference || "", idempotencyKey: createClientTransactionKey("stockvel_contribution") }
  });
  showToast(`Contribution of ${money(result.amount || amount)} made. Reference ${result.reference}.`);
  refreshData().catch(() => {});
  try { await openStockvelDashboard(groupId); } catch { closeModal(); }
}
// Save the wizard as a draft at any step: whatever is filled in survives on
// the server, appears on the hub with a draft chip, and activates later.
async function saveStockvelDraft() {
  const form = document.querySelector("[data-stockvel-wizard]");
  if (!form) return;
  const data = new FormData(form);
  const name = String(data.get("recipient") || "").trim();
  if (name.length < 2) { showToast("Give the group a name first. Everything else can wait.", "error"); return; }
  try {
    await api(STOCKVEL_PATH, {
      method: "POST",
      body: {
        name,
        description: String(data.get("description") || ""),
        cadence: String(data.get("cadence") || "monthly"),
        contributionAmount: String(data.get("amount") || "0"),
        goalAmount: String(data.get("stockvelSavingsGoal") || "") || null,
        memberLimit: String(data.get("memberLimit") || "") || null,
        status: "draft"
      }
    });
    closeModal();
    await loadStockvelGroups({ force: true }).catch(() => {});
    openStockvelModal();
    showToast(`"${name}" saved as a draft. Activate it when the group is ready.`);
  } catch (error) {
    showToast(friendlyFormError(error, "stockvel"), "error");
  }
}
async function submitStockvelChat(data) {
  const message = String(data.message || "").trim();
  if (!message) throw new Error("Write a message first.");
  await api(`${STOCKVEL_PATH}/${encodeURIComponent(data.groupId)}/messages`, { method: "POST", body: { message } });
  const form = document.querySelector('form[data-form="stockvel-chat"]');
  if (form) form.reset();
  await refreshStockvelGroupChat();
}

/* ==========================================================================
   19. EVENTS AND TICKETING
   ========================================================================== */

function localSupportTicketRef(prefix = "TC") {
  const cleanPrefix = String(prefix || "TC").replace(/[^A-Z]/gi, "").toUpperCase().slice(0, 2) || "TC";
  const tickets = readJson("titopay_support_requests") || [];
  const ratings = readJson("titopay_support_ratings") || [];
  const existing = new Set([...tickets, ...ratings].flatMap((item) => [item.ticketRef, item.ticket_ref, item.id].filter(Boolean).map(String)));
  for (let attempt = 0; attempt < 20; attempt += 1) {
    const bytes = new Uint32Array(1);
    if (window.crypto && window.crypto.getRandomValues) window.crypto.getRandomValues(bytes);
    const seed = bytes[0] || Math.floor(Math.random() * 1000000);
    const ref = `${cleanPrefix}${String(seed % 1000000).padStart(6, "0")}`;
    if (!existing.has(ref)) return ref;
  }
  return `${cleanPrefix}${String(Date.now()).slice(-6)}`;
}
async function openPersonalTicketsDashboard() {
  // Open immediately with a loading state rather than leaving the customer on a
  // dead tap while the events request is in flight.
  openModal(`
    <div class="modal-head">
      <div>
        <p class="eyebrow">TitoPay Tickets</p>
        <h2>What's on</h2>
        <p class="lead">Verified TitoPay events with secure digital tickets.</p>
      </div>
      <button class="icon-btn" data-close aria-label="Close">${icon("x")}</button>
    </div>
    <button class="btn secondary" type="button" data-action="my-tickets">${icon("ticket")} My Tickets</button>
    <div data-staff-scan-entry></div>
    <section class="ticket-list" data-ticket-list aria-live="polite">
      ${[0, 1, 2].map(() => `<div class="ticket-card is-loading" aria-hidden="true">
        <span class="skeleton skeleton-circle"></span>
        <div><span class="skeleton skeleton-line"></span><span class="skeleton skeleton-line short"></span></div>
      </div>`).join("")}
    </section>
  `);
  // If an organiser has added this person as event staff, the door scanner is
  // theirs too — surfaced here so a personal account can find it without any
  // business tile. Best-effort: no assignments (or an older API) shows nothing.
  if (state.auth?.accessToken) {
    api("/v1/ticketing/staff/events")
      .then((result) => {
        const assigned = Array.isArray(result.items) ? result.items : [];
        state.ticketing.staffEvents = assigned;
        const host = document.querySelector("[data-staff-scan-entry]");
        if (host && assigned.length) {
          host.innerHTML = `<button class="btn primary" type="button" data-action="ticketing-staff-open">${icon("scan")} Scan entry · staff for ${assigned.length === 1 ? esc(assigned[0].eventName || "an event") : `${assigned.length} events`}</button>`;
        }
      })
      .catch(() => null);
  }
  await refreshPublicTickets();
}
async function refreshPublicTickets() {
  const host = document.querySelector("[data-ticket-list]");
  if (!host) return;
  try {
    const result = await api("/v1/ticketing/public/events", { auth: false });
    state.ticketing.events = Array.isArray(result.items) ? result.items : [];
    state.ticketing.search = "";
    renderPublicTickets();
  } catch (error) {
    const current = document.querySelector("[data-ticket-list]");
    if (!current) return;
    const offline = Number(error?.status || 0) === 0;
    current.innerHTML = `
      <section class="empty-state compact-state">
        ${icon("ticket")}
        <strong>${offline ? "Cannot reach TitoPay" : "No events available right now"}</strong>
        <p>${offline ? "Check your connection and try again." : "Approved TitoPay events appear here as soon as ticket sales open."}</p>
        <button class="btn secondary" type="button" data-ticket-refresh="1">${icon("refresh")} Try again</button>
      </section>`;
  }
}
function renderPublicTickets() {
  const host = document.querySelector("[data-ticket-list]");
  if (!host) return;
  const events = state.ticketing.events || [];
  const needle = String(state.ticketing.search || "").trim().toLowerCase();
  const matches = events.filter((event) => !needle || [event.eventName, event.venueName, event.city, event.category]
    .filter(Boolean).some((value) => String(value).toLowerCase().includes(needle)));

  if (!events.length) {
    host.innerHTML = `
      <section class="empty-state compact-state">
        ${icon("ticket")}
        <strong>No events on sale yet</strong>
        <p>Approved TitoPay events appear here as soon as ticket sales open. Check back soon.</p>
        <button class="btn secondary" type="button" data-ticket-refresh="1">${icon("refresh")} Refresh</button>
      </section>`;
    return;
  }

  host.innerHTML = `
    ${events.length > 4 ? `<div class="ticket-search">
      <label class="visually-hidden" for="ticket-search">Search events</label>
      <input id="ticket-search" class="vas-search-input" type="search" autocomplete="off" data-ticket-search placeholder="Search events, venues or cities" value="${esc(state.ticketing.search || "")}">
    </div>` : ""}
    ${matches.length
      ? matches.map(ticketingPublicEventRow).join("")
      : `<section class="empty-state compact-state"><strong>No match</strong><p>Nothing matches "${esc(state.ticketing.search)}".</p></section>`}`;
}
function ticketingPublicEventRow(event = {}) {
  const tickets = Array.isArray(event.ticketTypes) ? event.ticketTypes : [];
  const prices = tickets.map((ticket) => Number(ticket.price || 0)).filter((price) => Number.isFinite(price));
  const lowestPrice = prices.length ? Math.min(...prices) : 0;
  const available = tickets.reduce((total, ticket) => total + Math.max(0, Number(ticket.quantityAvailable || 0) - Number(ticket.quantitySold || 0)), 0);
  const date = event.eventDate ? new Date(event.eventDate) : null;
  const validDate = date && !Number.isNaN(date.getTime());
  const soldOut = tickets.length > 0 && available === 0;
  return `
    <article class="ticket-card${soldOut ? " is-sold-out" : ""}">
      <div class="ticket-date" aria-hidden="true">
        <span>${esc(validDate ? date.toLocaleDateString("en-ZA", { month: "short" }) : "TBC")}</span>
        <strong>${esc(validDate ? String(date.getDate()) : "--")}</strong>
      </div>
      <div class="ticket-body">
        <strong>${esc(event.eventName || "TitoPay Event")}</strong>
        <small>${esc(validDate ? date.toLocaleDateString("en-ZA", { weekday: "short", day: "2-digit", month: "long", year: "numeric" }) : "Date to be confirmed")}</small>
        <small>${icon("globe")} ${esc([event.venueName, event.city].filter(Boolean).join(", ") || "Venue to be confirmed")}</small>
        <div class="ticket-meta">
          <span class="ticket-price">${prices.length ? `From ${esc(money(lowestPrice))}` : "Price to be confirmed"}</span>
          ${soldOut ? `<em class="sv-chip failed">Sold out</em>` : available ? `<em class="sv-chip settled">${available} available</em>` : ""}
        </div>
      </div>
      <button class="btn secondary ticket-cta" type="button" data-action="ticketing-open-event:${esc(event.slug || "")}"${soldOut ? " disabled" : ""}>${soldOut ? "Sold out" : "View"}</button>
    </article>
  `;
}
